package com.friendworldactivity;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class FriendWorldActivityPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(FriendWorldActivityPlugin.class);
		RuneLite.main(args);
	}
}

package com.friendworldactivity;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

public class FriendWorldActivityFormattingTest
{
	@Test
	public void normalizesMissingActivities()
	{
		assertNull(FriendWorldActivityPlugin.normalizeActivity(null));
		assertNull(FriendWorldActivityPlugin.normalizeActivity(""));
		assertNull(FriendWorldActivityPlugin.normalizeActivity(" - "));
	}

	@Test
	public void keepsLiveActivityText()
	{
		assertEquals("Nex FFA", FriendWorldActivityPlugin.normalizeActivity(" Nex FFA "));
		assertEquals("World 332: Nex FFA",
			FriendWorldActivityPlugin.formatTooltip(332, "Nex FFA", false));
	}

	@Test
	public void canHideOrShowUnlabelledWorlds()
	{
		assertNull(FriendWorldActivityPlugin.formatTooltip(301, null, false));
		assertEquals("World 301: No listed activity",
			FriendWorldActivityPlugin.formatTooltip(301, null, true));
	}
}

package com.friendworldactivity;

import com.google.inject.Provides;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ScheduledExecutorService;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Friend;
import net.runelite.api.FriendContainer;
import net.runelite.api.MenuEntry;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.WidgetUtil;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.WorldsFetch;
import net.runelite.client.game.WorldService;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.Text;
import net.runelite.http.api.worlds.World;
import net.runelite.http.api.worlds.WorldResult;

@PluginDescriptor(
	name = "Friend World Activity",
	description = "Shows the live activity of a friend's world in a tooltip",
	tags = {"friends", "world", "activity", "tooltip", "notes"}
)
public class FriendWorldActivityPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private FriendWorldActivityConfig config;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private FriendWorldActivityOverlay overlay;

	@Inject
	private WorldService worldService;

	@Inject
	private ScheduledExecutorService executor;

	private volatile Map<Integer, String> activitiesByWorld = Collections.emptyMap();

	@Provides
	FriendWorldActivityConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(FriendWorldActivityConfig.class);
	}

	@Override
	protected void startUp()
	{
		overlayManager.add(overlay);
		// WorldService can wait for its first fetch, so keep that work off the client thread.
		executor.execute(() -> updateWorlds(worldService.getWorlds()));
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		activitiesByWorld = Collections.emptyMap();
	}

	@Subscribe
	public void onWorldsFetch(WorldsFetch event)
	{
		updateWorlds(event.getWorldResult());
	}

	String getHoveredWorldTooltip()
	{
		if (client.isMenuOpen())
		{
			return null;
		}
		for (MenuEntry entry : client.getMenuEntries())
		{
			if ("Message".equals(entry.getOption()) &&
				WidgetUtil.componentToInterface(entry.getParam1()) == InterfaceID.FRIENDS)
			{
				return getFriendTooltip(entry.getTarget());
			}
		}
		return null;
	}

	private String getFriendTooltip(String target)
	{
		final String displayName = Text.toJagexName(Text.removeTags(target));
		final FriendContainer friends = client.getFriendContainer();
		final Friend friend = friends == null ? null : friends.findByName(displayName);
		if (friend == null || friend.getWorld() <= 0)
		{
			return null;
		}

		final int worldId = friend.getWorld();
		final String activity = activitiesByWorld.get(worldId);
		return formatTooltip(worldId, activity, config.showUnlabelledWorlds());
	}

	private void updateWorlds(WorldResult result)
	{
		if (result == null || result.getWorlds() == null)
		{
			return;
		}

		final Map<Integer, String> updated = new HashMap<>();
		for (World world : result.getWorlds())
		{
			updated.put(world.getId(), normalizeActivity(world.getActivity()));
		}
		activitiesByWorld = Collections.unmodifiableMap(updated);
	}

	static String formatTooltip(int worldId, String activity, boolean showUnlabelledWorlds)
	{
		if (activity == null && !showUnlabelledWorlds)
		{
			return null;
		}

		return "World " + worldId + ": " + (activity == null ? "No listed activity" : activity);
	}

	static String normalizeActivity(String activity)
	{
		if (activity == null)
		{
			return null;
		}

		final String trimmed = activity.trim();
		return trimmed.isEmpty() || "-".equals(trimmed) ? null : trimmed;
	}
}

package com.friendworldactivity;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(FriendWorldActivityConfig.GROUP)
public interface FriendWorldActivityConfig extends Config
{
	String GROUP = "friend-world-activity";

	@ConfigItem(
		keyName = "showUnlabelledWorlds",
		name = "Show unlabelled worlds",
		description = "Show a tooltip for worlds that have no activity label"
	)
	default boolean showUnlabelledWorlds()
	{
		return false;
	}
}

package com.friendworldactivity;

import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.tooltip.Tooltip;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;

public class FriendWorldActivityOverlay extends Overlay
{
	private final FriendWorldActivityPlugin plugin;
	private final TooltipManager tooltipManager;

	@Inject
	FriendWorldActivityOverlay(FriendWorldActivityPlugin plugin, TooltipManager tooltipManager)
	{
		this.plugin = plugin;
		this.tooltipManager = tooltipManager;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		// RuneLite clears the tooltip queue after every frame. Replenish it on
		// every render, including frames between menu-building game cycles.
		String text = plugin.getHoveredWorldTooltip();
		if (text != null)
		{
			tooltipManager.add(new Tooltip("<col=00ff00>" + text + "</col>"));
		}
		return null;
	}
}
